163	fn fixed_size_to_offsets<O: Offset>(values_len: usize, fixed_size: usize) -> Offsets<O> {
164	    let offsets = (0..(values_len + 1))
165	        .step_by(fixed_size)
166	        .map(|v| O::from_as_usize(v))
167	        .collect();
168	    // SAFETY:
169	    // * every element is `>= 0`
170	    // * element at position `i` is >= than element at position `i-1`.
171	    unsafe { Offsets::new_unchecked(offsets) }
172	}
