253	/// Returns a new `ArrowSchema` that will have Polars-specific metadata attached for e.g. Categorical
254	/// and Enum types.
255	pub(crate) fn validate_arrow_schema_conversion(
256	    input_schema: &Schema,
257	    expected_arrow_schema: &ArrowSchema,
258	) -> PolarsResult<ArrowSchema> {
259	    polars_ensure!(
260	        input_schema.len() == expected_arrow_schema.len()
261	        && input_schema
262	            .iter_names()
263	            .zip(expected_arrow_schema.iter_names())
264	            .all(|(l, r)| l == r),
265	        SchemaMismatch:
266	        "schema names in arrow_schema differ: {:?} != arrow schema names: {:?}",
267	        input_schema.names_display(),
268	        expected_arrow_schema.values_display(),
269	    );
270	
271	    // Put everything into a struct column and convert that to arrow. This way
272	    // top-level columns become `ArrowField`s and the metadata is set properly.
273	    feature_gated!("dtype-struct", {
274	        let pl_struct_series = Series::full_null(
275	            PlSmallStr::EMPTY,
276	            0,
277	            &DataType::Struct(input_schema.iter_fields().collect()),
278	        );
279	
280	        let arrow_array = pl_struct_series.to_arrow_with_field(
281	            0,
282	            Cow::Owned(ArrowField::new(
283	                PlSmallStr::EMPTY,
284	                ArrowDataType::Struct(expected_arrow_schema.iter_values().cloned().collect()),
285	                false,
286	            )),
287	            false,
288	        )?;
289	
290	        let ArrowDataType::Struct(fields) = arrow_array.dtype() else {
291	            unreachable!()
292	        };
293	
294	        let mut out = ArrowSchema::from_iter(fields.iter().cloned());
295	        *out.metadata_mut() = expected_arrow_schema.metadata().clone();
296	
297	        Ok(out)
298	    })
299	}
